const order=['grunt','tallGrunt','archer','priest','trebuchet','mount','air','poisonDragon','fireDragon','iceDragon','iceDemon','fireDemon'];
const randomOrder=['fireDragon','iceDragon','poisonDragon','fireDemon','iceDemon'];
export function getLevel(number){if(!Number.isInteger(number)||number<1||number>30)throw new RangeError('Campaign battle must be 1 through 30');return LEVELS[number-1];}
export function levelTerrain(number){return new HeightField(getLevel(number).heights);}
export function campaignRoster(number,random=Math.random){const data=getLevel(number),counts={...data.fixedCounts};for(const key of randomOrder){const config=data.randomCounts[key];counts[key]=config.draw?Math.floor(random()*config.limit):0;}const pool=[];for(const key of order)for(let i=0;i<(counts[key]??0);i++)pool.push(key);const result=[];while(pool.length)result.push(pool.splice(Math.floor(random()*pool.length),1)[0]);for(let i=0;i<(counts.gorath??0);i++)result.push('gorath');return result.reverse();}
export function campaignTowerCount(level,random=Math.random){const limit=Math.floor(level/7);return Math.min(3,limit>0?Math.floor(random()*limit):0);}
